INSERT INTO `tl_theme` (`id`, `tstamp`, `name`, `author`, `folders`, `screenshot`, `templates`, `pdir_th_description`, `pdir_th_license_domain`, `pdir_th_short_code`) VALUES(17, 1566205456, 'Odd Theme', 'pdir digital agentur // pdir GmbH / Juliane Langer, Philipp Seibt, Mathias Arzberger', NULL, NULL, '', '&lt;b&#62;pdir contao theme licence&lt;/b&#62;&lt;br&#62;\nMit dieser &lt;b&#62;Lizenz&lt;/b&#62; gekennzeichnete Themes dürfen sowohl privat als auch kommerziell eingesetzt werden. Der Copyright-Link bzw. die Copyright-Links \"&lt;i&#62;ODD Theme by montequesto&lt;/i&#62;\" dürfen nicht entfernt oder verändert werden. Das gilt auch wenn Sie das Theme\nnur als Basis für eine Website einsetzen und es verändern.\nMöchten Sie diesen Theme ohne Copyright-Link einsetzen, müssen Sie eine kostenpflichtige Lizenz erwerben.', '', 'odd');
